CREATE TABLE treat_orders (
  id INTEGER PRIMARY KEY, number TEXT NOT NULL UNIQUE, company_id INTEGER NOT NULL, point_id INTEGER NOT NULL, kind TEXT NOT NULL,
  date_from TEXT NOT NULL, date_to TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'planificata', responsible TEXT, notes TEXT,
  created TEXT, created_by TEXT, started_at TEXT, finished_at TEXT, finished_by TEXT, cancel_reason TEXT
);
CREATE TABLE treat_sessions (
  id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL, point_id INTEGER NOT NULL, day TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'deschisa',
  opened_at TEXT, opened_by TEXT, closed_at TEXT, closed_by TEXT, UNIQUE (point_id, day)
);
CREATE TABLE treat_ops (
  id INTEGER PRIMARY KEY, number TEXT NOT NULL UNIQUE, session_id INTEGER NOT NULL REFERENCES treat_sessions(id), company_id INTEGER NOT NULL,
  point_id INTEGER NOT NULL, kind TEXT NOT NULL, treat_order_id INTEGER, status TEXT NOT NULL DEFAULT 'deschisa', notes TEXT,
  created TEXT, created_by TEXT, closed_at TEXT, closed_by TEXT, cancel_reason TEXT
);
CREATE TABLE treat_inputs (
  id INTEGER PRIMARY KEY, op_id INTEGER NOT NULL REFERENCES treat_ops(id), stock_id INTEGER NOT NULL, from_stock_id INTEGER NOT NULL,
  split INTEGER DEFAULT 0, prev_status TEXT, prev_res_treat_id INTEGER, prev_res_note TEXT, kg REAL NOT NULL, pcs INTEGER, created TEXT, created_by TEXT
);
CREATE TABLE treat_outputs (
  id INTEGER PRIMARY KEY, op_id INTEGER NOT NULL REFERENCES treat_ops(id), article_id INTEGER NOT NULL, ewc_id INTEGER, hu_id INTEGER,
  lot TEXT NOT NULL, kg REAL NOT NULL, pcs INTEGER, org_id INTEGER, regime TEXT DEFAULT 'propriu', stock_id INTEGER, created TEXT, created_by TEXT
);
